import type { Locale } from '@/lib/i18n';
import { ltr } from './bidi';

/** Localizes IPAM conflict evidence sentences generated by `apps/api/src/modules/ipam/plan.ts`. */
export function localizeIpamEvidence(line: string, locale: Locale): string {
  if (locale !== 'ar') return line;

  let m = line.match(/^(.+?) reported online at ([0-9.]+), last seen (.+)$/);
  if (m) return `الجهاز ${ltr(m[1]!)} مُسجَّل كمتصل على ${ltr(m[2]!)}، آخر ظهور ${ltr(m[3]!)}`;

  m = line.match(/^([0-9.]+) is documented as reserved \("(.+)"\)$/);
  if (m) return `العنوان ${ltr(m[1]!)} موثَّق كمحجوز («${m[2]}»)`;

  m = line.match(/^(.+?) is online at this address$/);
  if (m) return `الجهاز ${ltr(m[1]!)} متصل حاليًا على هذا العنوان`;

  m = line.match(/^([0-9.]+) is documented for (.+) \(([0-9a-f:]+)\)$/i);
  if (m) return `العنوان ${ltr(m[1]!)} موثَّق للجهاز ${m[2]} (${ltr(m[3]!)})`;

  m = line.match(/^The device online at this address is (.+) \(([0-9a-f:]+)\)$/i);
  if (m) return `الجهاز المتصل حاليًا على هذا العنوان هو ${m[1]} (${ltr(m[2]!)})`;

  m = line.match(/^([0-9.]+) is documented as a static address \("(.+)"\)$/);
  if (m) return `العنوان ${ltr(m[1]!)} موثَّق كعنوان ثابت («${m[2]}»)`;

  m = line.match(/^It is inside the DHCP pool ([0-9.]+) – ([0-9.]+), so the DHCP server may hand it to another device$/);
  if (m) return `يقع داخل نطاق DHCP (${ltr(`${m[1]} – ${m[2]}`)})، ما قد يجعل خادم DHCP يمنحه لجهاز آخر`;

  return line;
}

/** Localizes endpoint compliance reasons generated by `apps/api/src/modules/endpoints/capabilities.ts`. */
export function localizeComplianceReason(reason: string, locale: Locale): string {
  if (locale !== 'ar') return reason;
  if (reason === 'Host firewall is reported off') return 'جدار الحماية على الجهاز متوقف';
  if (reason === 'Antivirus protection is reported disabled') return 'مكافح الفيروسات معطّل';

  let m = reason.match(/^Disk usage is critically high \(([0-9.]+)%\)$/);
  if (m) return `امتلاء القرص وصل لمستوى حرج (${ltr(`${m[1]}%`)})`;

  m = reason.match(/^(\d+) OS\/security update\(s\) pending$/);
  if (m) return `توجد ${ltr(m[1]!)} تحديثات نظام/أمان معلّقة`;

  return reason;
}

/** Localizes auto-generated incident titles into native Arabic while leaving custom text intact. */
export function localizeIncidentTitle(title: string, locale: Locale): string {
  if (locale !== 'ar') return title;

  const exact: Record<string, string> = {
    'Local gateway is not responding': 'البوابة الافتراضية لا تستجيب',
    'Local network segment failure': 'عطل في جزء من الشبكة المحلية',
    'Internet connection is down (WAN / ISP)': 'انقطاع الاتصال بالإنترنت (WAN / مزوّد الخدمة)',
    'One internet destination is unreachable': 'وجهة إنترنت واحدة لا تستجيب',
    'DNS resolution is failing': 'فشل ترجمة الأسماء (DNS)',
    'DNS resolution is slow': 'بطء في ترجمة الأسماء (DNS)',
    'Local network path is degraded': 'تراجع جودة المسار في الشبكة المحلية',
    'Internet connection is slow or lossy': 'اتصال الإنترنت بطيء أو يفقد حزمًا',
    'No DHCP server is answering': 'لا يوجد خادم DHCP يستجيب',
  };
  if (exact[title]) return exact[title]!;

  let m = title.match(/^Collector "(.+)" (?:lost contact|is offline|went offline)$/);
  if (m) return `فقد المجمِّع «${m[1]}» الاتصال`;

  m = title.match(/^(.+) is offline$/);
  if (m) return `${m[1]} غير متصل`;

  m = title.match(/^(.+) is offline — part of a wider problem$/);
  if (m) return `${m[1]} غير متصل — ضمن مشكلة أوسع`;

  m = title.match(/^(.+): (?:down|not responding)$/);
  if (m) return `${m[1]}: لا يستجيب`;

  m = title.match(/^(.+): service is not listening$/);
  if (m) return `${m[1]}: الخدمة لا تستمع على المنفذ`;

  m = title.match(/^(.+): the host is offline$/);
  if (m) return `${m[1]}: الجهاز المضيف غير متصل`;

  m = title.match(/^Unexpected DHCP server (.+)$/);
  if (m) return `خادم DHCP غير متوقَّع ${ltr(m[1]!)}`;

  return title;
}

/** Localizes system-generated incident activity messages (keeps user comments untouched). */
export function localizeIncidentActivity(body: string, kind: string, locale: Locale): string {
  if (locale !== 'ar' || kind === 'comment') return body;

  if (body === 'Incident opened') return 'تم فتح الحادثة';
  if (body === 'Incident acknowledged') return 'تم الإقرار بالحادثة';
  if (body === 'Incident resolved automatically') return 'تم حل الحادثة تلقائيًا';
  if (body === 'Incident resolved manually') return 'تم حل الحادثة يدويًا';
  if (body === 'Diagnosis updated') return 'تم تحديث التشخيص';

  let m = body.match(/^Assigned to (.+)$/);
  if (m) return `تم الإسناد إلى ${m[1]}`;

  m = body.match(/^Opened from (.+)$/);
  if (m) return `فُتحت الحادثة بسبب: ${m[1]}`;

  m = body.match(/^Resolved: (.+)$/);
  if (m) return `تم الحل: ${m[1]}`;

  return body;
}

